import os
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps
import hashlib
import time

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/data/inventory.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        key = request.headers.get('X-API-Key')
        if not key:
            return jsonify({'error': 'Missing API key'}), 401
        db = get_db()
        row = db.execute('SELECT * FROM api_keys WHERE key_value = ?', (key,)).fetchone()
        if not row:
            return jsonify({'error': 'Invalid API key'}), 403
        g.current_user = dict(row)
        return f(*args, **kwargs)
    return decorated

def audit_log(action, details):
    """Write audit entry - uses parameterized query"""
    db = get_db()
    db.execute('INSERT INTO audit_log (timestamp, action, details, user_id) VALUES (?, ?, ?, ?)',
               (time.time(), action, details, g.get('current_user', {}).get('id', 'anon')))
    db.commit()

@app.route('/api/products/search', methods=['GET'])
@require_api_key
def search_products():
    """Search products with filters"""
    name = request.args.get('name', '')
    category = request.args.get('category', '')
    supplier = request.args.get('supplier', '')
    sort_by = request.args.get('sort', 'name')

    # Validate sort column against allowlist
    allowed_sorts = ['name', 'category', 'price', 'quantity', 'supplier']
    if sort_by not in allowed_sorts:
        sort_by = 'name'

    # Build query with filters
    conditions = []
    if name:
        conditions.append(f"name LIKE '%{name}%'")
    if category:
        conditions.append(f"category = '{category}'")
    if supplier:
        conditions.append(f"supplier = '{supplier}'")

    query = "SELECT id, name, category, price, quantity, supplier FROM products"
    if conditions:
        query += " WHERE " + " AND ".join(conditions)
    query += f" ORDER BY {sort_by} LIMIT 100"

    audit_log('product_search', f'query_params: name={name}, category={category}')

    db = get_db()
    try:
        results = db.execute(query).fetchall()
        return jsonify({'products': [dict(r) for r in results]})
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/products/<int:product_id>', methods=['GET'])
@require_api_key
def get_product(product_id):
    db = get_db()
    row = db.execute('SELECT * FROM products WHERE id = ?', (product_id,)).fetchone()
    if not row:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(dict(row))

@app.route('/api/products', methods=['POST'])
@require_api_key
def create_product():
    data = request.get_json()
    if not data or 'name' not in data:
        return jsonify({'error': 'Name required'}), 400
    db = get_db()
    db.execute('INSERT INTO products (name, category, price, quantity, supplier) VALUES (?, ?, ?, ?, ?)',
               (data['name'], data.get('category', ''), data.get('price', 0),
                data.get('quantity', 0), data.get('supplier', '')))
    db.commit()
    audit_log('product_create', f'name={data["name"]}')
    return jsonify({'status': 'created'}), 201

@app.route('/api/inventory/report', methods=['GET'])
@require_api_key
def inventory_report():
    """Generate inventory summary - read only, parameterized"""
    db = get_db()
    rows = db.execute(
        'SELECT category, COUNT(*) as count, SUM(quantity) as total_qty, '
        'AVG(price) as avg_price FROM products GROUP BY category'
    ).fetchall()
    return jsonify({'report': [dict(r) for r in rows]})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
